#!/usr/bin/env bash
# MaCod Phase 4 rebrand script.
#
# Sweeps brand strings and relative imports across the repo, then renames
# the four package directories cod-* → macod-*.
#
# Skipped (intentionally):
#   - macod-server/src/db/migrations/*.sql  — historical record of applied migrations
#   - package-lock.json                   — regenerated by `npm ci`
#   - .git/                               — version control
#   - node_modules/                       — installed deps
#
# Run from the repo root:  bash scripts/rebrand-to-macod.sh
# After running: `npm ci` to regenerate the lockfile, then `npx tsc --noEmit`
# in each package to verify imports resolve.

set -euo pipefail

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
cd "$ROOT"

echo "→ MaCod rebrand: sweeping brand strings + relative imports..."

# Build the list of files to edit. Skip migrations, lockfile, git, node_modules.
mapfile -t FILES < <( \
  grep -rIl \
    --exclude-dir=.git \
    --exclude-dir=node_modules \
    --exclude-dir=.wrangler-shared \
    --exclude='package-lock.json' \
    --exclude-dir=migrations \
    -e 'macod' -e 'MaCod' -e 'macod' \
    -e 'macod-shared' -e 'macod-server' -e 'macod-client-astro' -e 'macod-astro' \
    -e 'MACOD_ACCOUNT_ID' -e 'MACOD_DB_NAME' -e 'MACOD_R2_BUCKET_NAME' \
    -e 'MACOD_SERVER_URL' -e 'MACOD_MEDIA_DOMAIN' \
    . \
)

echo "  → $(printf '%s\n' "${FILES[@]}" | wc -l) files to edit"

# ── Brand strings ────────────────────────────────────────────────────────────
# Order matters: longer/more-specific patterns first so they win.
#   MaCod      → MaCod       (proper noun, brand name)
#   macod      → macod       (lowercase: package names, URLs, db names)
#   macod     → macod       (kebab form, rare)
#   COD_         → MACOD_      (env var prefix — keeps precedence chain working)

# ── Relative imports & path references ────────────────────────────────────────
#   macod-shared       → macod-shared
#   macod-server       → macod-server
#   macod-client-astro → macod-client-astro   (keep the -astro suffix — it's an Astro app)
#   macod-astro        → macod-astro

for f in "${FILES[@]}"; do
  # Use perl for the substitution so we get word-boundary-safe replacements
  # without touching substrings (e.g. "macod-shared" inside "macod-shared"
  # after the first pass — but we only do one pass per pattern, so this is fine).
  perl -i -pe '
    s/\bCodFlow\b/MaCod/g;
    s/\bcod-flow\b/macod/g;
    s/\bcodflow\b/macod/g;
    s/\bcod-shared\b/macod-shared/g;
    s/\bcod-server\b/macod-server/g;
    s/\bcod-client-astro\b/macod-client-astro/g;
    s/\bcod-astro\b/macod-astro/g;
    s/\bCOD_ACCOUNT_ID\b/MACOD_ACCOUNT_ID/g;
    s/\bCOD_DB_NAME\b/MACOD_DB_NAME/g;
    s/\bCOD_R2_BUCKET_NAME\b/MACOD_R2_BUCKET_NAME/g;
    s/\bCOD_SERVER_URL\b/MACOD_SERVER_URL/g;
    s/\bCOD_MEDIA_DOMAIN\b/MACOD_MEDIA_DOMAIN/g;
  ' "$f"
done

echo "✓ Brand + import sweep complete"

# ── Rename directories ───────────────────────────────────────────────────────
echo "→ Renaming package directories cod-* → macod-*..."

# Order: rename the longest path first so we don't shadow shorter names.
# macod-client-astro  → macod-client-astro  (must run before macod-astro)
# macod-shared        → macod-shared
# macod-server        → macod-server
# macod-astro         → macod-astro  (parent of theme01)

if [ -d macod-client-astro ]; then
  mv macod-client-astro macod-client-astro
  echo "  ✓ macod-client-astro → macod-client-astro"
fi
if [ -d macod-shared ]; then
  mv macod-shared macod-shared
  echo "  ✓ macod-shared → macod-shared"
fi
if [ -d macod-server ]; then
  mv macod-server macod-server
  echo "  ✓ macod-server → macod-server"
fi
if [ -d macod-astro ]; then
  mv macod-astro macod-astro
  echo "  ✓ macod-astro → macod-astro"
fi

echo "✓ Directory rename complete"
echo ""
echo "→ MaCod rebrand complete. Next steps:"
echo "  1. npm ci                                  # regenerate lockfile"
echo "  2. cd macod-server && npx tsc --noEmit      # verify imports"
echo "  3. cd macod-client-astro && npx astro check"
echo "  4. cd macod-astro/theme01 && npx vitest --run"
